8	/**
9	 * Utility that allows for setting system properties when it's created and resetting them when it's closed.
10	 * This is meant to be used in try-with-resources statements
11	 */
12	public class ResettableSystemProperties implements AutoCloseable {
13	
14	    private final Map<String, String> toRestore;
15	
16	    public ResettableSystemProperties(Map<String, String> toSet) {
17	        Objects.requireNonNull(toSet);
18	        if (toSet.isEmpty()) {
19	            toRestore = Collections.emptyMap();
20	            return;
21	        }
22	        toRestore = new HashMap<>();
23	        for (var entry : toSet.entrySet()) {
24	            String oldValue = System.setProperty(entry.getKey(), entry.getValue());
25	            toRestore.put(entry.getKey(), oldValue);
26	        }
27	    }
28	
29	    public static ResettableSystemProperties of(String name, String value) {
30	        return new ResettableSystemProperties(Map.of(name, value));
31	    }
32	
33	    public static ResettableSystemProperties empty() {
34	        return new ResettableSystemProperties(Collections.emptyMap());
35	    }
36	
37	    @Override
38	    public void close() {
39	        for (var entry : toRestore.entrySet()) {
40	            if (entry.getValue() != null) {
41	                System.setProperty(entry.getKey(), entry.getValue());
42	            } else {
43	                System.clearProperty(entry.getKey());
44	            }
45	        }
46	    }
