9	class ResettableSystemPropertiesTest {
10	
11	    @Test
12	    public void happyPath() {
13	        System.setProperty("prop1", "val1");
14	        assertThat(System.getProperty("prop1")).isEqualTo("val1");
15	        try (var ignored = new ResettableSystemProperties(
16	                Map.of("prop1", "val11", "prop2", "val2"))) {
17	            assertThat(System.getProperty("prop1")).isEqualTo("val11");
18	            assertThat(System.getProperty("prop2")).isEqualTo("val2");
19	        }
20	        assertThat(System.getProperty("prop1")).isEqualTo("val1");
21	        assertThat(System.getProperties()).doesNotContainKey("prop2");
22	    }
23	
24	    @Test
25	    public void exceptionThrown() {
26	        System.setProperty("prop1", "val1");
27	        int initCount = System.getProperties().size();
28	        assertThat(System.getProperty("prop1")).isEqualTo("val1");
29	        try (var ignored = new ResettableSystemProperties(
30	                Map.of("prop1", "val11", "prop2", "val2"))) {
31	            assertThat(System.getProperty("prop1")).isEqualTo("val11");
32	            assertThat(System.getProperty("prop2")).isEqualTo("val2");
33	
34	            throw new RuntimeException("dummy");
35	        } catch (Exception ignored) {
36	
37	        }
38	        assertThat(System.getProperty("prop1")).isEqualTo("val1");
39	        assertThat(System.getProperties()).doesNotContainKey("prop2");
40	        assertThat(System.getProperties().size()).isEqualTo(initCount);
41	    }
