25	
26	public class LiquibaseFactory {
27	
28	    private final DataSource dataSource;
29	
30	    private final String dataSourceName;
31	
32	    private final LiquibaseConfig config;
33	
34	    public LiquibaseFactory(LiquibaseConfig config, DataSource datasource, String dataSourceName) {
35	        this.config = config;
36	        this.dataSource = datasource;
37	        this.dataSourceName = dataSourceName;
38	    }
39	
40	    private ResourceAccessor resolveResourceAccessor() throws FileNotFoundException {
41	
42	        CompositeResourceAccessor compositeResourceAccessor = new CompositeResourceAccessor();
43	        compositeResourceAccessor
44	                .addResourceAccessor(new ClassLoaderResourceAccessor(Thread.currentThread().getContextClassLoader()));
45	
46	        if (!config.changeLog.startsWith("filesystem:") && config.searchPath.isEmpty()) {
47	            return compositeResourceAccessor;
48	        }
49	
50	        if (config.searchPath.isEmpty()) {
51	            compositeResourceAccessor.addResourceAccessor(
52	                    new DirectoryResourceAccessor(
53	                            Paths.get(StringUtil.changePrefix(config.changeLog, "filesystem:", "")).getParent()));
54	            return compositeResourceAccessor;
55	        }
56	
57	        for (String searchPath : config.searchPath.get()) {
58	            compositeResourceAccessor.addResourceAccessor(new DirectoryResourceAccessor(Paths.get(searchPath)));
59	        }
60	
61	        return compositeResourceAccessor;
62	    }
63	
64	    private String parseChangeLog(String changeLog) {
65	
66	        if (changeLog.startsWith("filesystem:") && config.searchPath.isEmpty()) {
67	            return Paths.get(StringUtil.changePrefix(changeLog, "filesystem:", "")).getFileName().toString();
68	        }
69	
70	        if (changeLog.startsWith("filesystem:")) {
71	            return StringUtil.changePrefix(changeLog, "filesystem:", "");
72	        }
73	
74	        if (changeLog.startsWith("classpath:")) {
75	            return StringUtil.changePrefix(changeLog, "classpath:", "");
76	        }
77	
78	        return changeLog;
79	    }
80	
81	    public Liquibase createLiquibase() {
82	        try (ResourceAccessor resourceAccessor = resolveResourceAccessor()) {
83	            String parsedChangeLog = parseChangeLog(config.changeLog);
84	
85	            Database database;
86	
87	            if (config.username.isPresent() && config.password.isPresent()) {
88	                AgroalDataSource agroalDataSource = dataSource.unwrap(AgroalDataSource.class);
89	                String jdbcUrl = agroalDataSource.getConfiguration().connectionPoolConfiguration()
90	                        .connectionFactoryConfiguration().jdbcUrl();
91	                Connection connection = DriverManager.getConnection(jdbcUrl, config.username.get(), config.password.get());
92	
93	                database = DatabaseFactory.getInstance()
94	                        .findCorrectDatabaseImplementation(
95	                                new JdbcConnection(connection));
96	
97	            } else {
98	                database = DatabaseFactory.getInstance()
99	                        .findCorrectDatabaseImplementation(new JdbcConnection(dataSource.getConnection()));
100	            }
101	
102	            if (database != null) {
103	                database.setDatabaseChangeLogLockTableName(config.databaseChangeLogLockTableName);
104	                database.setDatabaseChangeLogTableName(config.databaseChangeLogTableName);
105	                config.liquibaseCatalogName.ifPresent(database::setLiquibaseCatalogName);
106	                config.liquibaseSchemaName.ifPresent(database::setLiquibaseSchemaName);
107	                config.liquibaseTablespaceName.ifPresent(database::setLiquibaseTablespaceName);
108	
109	                if (config.defaultCatalogName.isPresent()) {
110	                    database.setDefaultCatalogName(config.defaultCatalogName.get());
111	                }
112	                if (config.defaultSchemaName.isPresent()) {
113	                    database.setDefaultSchemaName(config.defaultSchemaName.get());
114	                }
115	            }
116	            Liquibase liquibase = new Liquibase(parsedChangeLog, resourceAccessor, database);
117	
118	            for (Map.Entry<String, String> entry : config.changeLogParameters.entrySet()) {
119	                liquibase.getChangeLogParameters().set(entry.getKey(), entry.getValue());
120	            }
121	
122	            return liquibase;
123	
124	        } catch (Exception ex) {
125	            throw new IllegalStateException(ex);
126	        }
127	    }
128	
129	    public LiquibaseConfig getConfiguration() {
130	        return config;
131	    }
132	
133	    /**
134	     * Creates the default labels base on the configuration
135	     *
136	     * @return the label expression
137	     */
138	    public LabelExpression createLabels() {
139	        return new LabelExpression(config.labels);
140	    }
141	
142	    /**
143	     * Creates the default contexts base on the configuration
144	     *
145	     * @return the contexts
146	     */
147	    public Contexts createContexts() {
148	        return new Contexts(config.contexts);
149	    }
150	
151	    public String getDataSourceName() {
152	        return dataSourceName;
153	    }
154	
155	    public ResettableSystemProperties createResettableSystemProperties() {
156	        if (config.allowDuplicatedChangesetIdentifiers.isEmpty()) {
157	            return ResettableSystemProperties.empty();
158	        }
159	        return ResettableSystemProperties.of("liquibase.allowDuplicatedChangesetIdentifiers",
160	                config.allowDuplicatedChangesetIdentifiers.get().toString());
161	    }
162	}
